<?php declare(strict_types=1); namespace Annam; $title='Checkout'; ?>
<section class="wrap php-store-section php-checkout-page php-checkout-flow"><div class="page-intro"><p class="section-kicker">1 · Delivery details</p><h1>Good food, delivered to you.</h1><p>Meals are delivered only to the kitchen’s serviceable pincodes. Shop items outside Chennai use courier delivery.</p></div><div class="checkout-layout"><form method="post" id="delivery-details" class="checkout-card checkout-form" data-checkout-delivery data-meal-delivery="<?= ($quote['cart']['kind']??'')==='scheduled'?'1':'0' ?>"><?= csrf() ?><?php if(!empty($form_error)):?><div class="checkout-errors php-error" role="alert" tabindex="-1" id="checkout-errors"><?= e($form_error) ?></div><?php endif;?><h2>Your delivery address</h2><p class="checkout-note" data-address-feedback role="status" aria-live="polite">For repeat orders, your saved address on this browser is filled for the same pincode. You can edit it below.</p><p class="checkout-note">Pincode is mandatory. We can’t accept a meal order outside our delivery coverage.</p><div class="checkout-fields"><?php foreach(['name'=>'Full name','phone'=>'Mobile number','email'=>'Email','pincode'=>'Delivery pincode','state'=>'State / province','country'=>'Country','line1'=>'Door number, building and street','line2'=>'Area / locality','city'=>'Town / city','landmark'=>'Landmark'] as $key=>$label): ?><label class="checkout-field <?= in_array($key,['line1','line2'])?'checkout-field-wide':'' ?>"><span><?= e($label) ?> <?= in_array($key,['email','line2','landmark','state','country'])?'<small>(optional)</small>':'<b>*</b>' ?></span><input class="checkout-input" name="<?= e($key) ?>" value="<?= e($form_values[$key]??(['country'=>'India','state'=>'Tamil Nadu','pincode'=>$_SESSION['cart']['pincode']??''][$key]??'')) ?>" <?= in_array($key,['email','line2','landmark','state','country'])?'':'required' ?> <?= $key==='email'?'type="email"':($key==='phone'?'type="tel" autocomplete="tel" aria-describedby="phone-help"':'') ?> maxlength="<?= $key==='pincode'?20:($key==='phone'?20:200) ?>"><?php if($key==='phone'):?><small id="phone-help">Enter 10 digits, or include the country code, e.g. +91 98765 43210.</small><?php endif;?></label><?php endforeach; ?>
<label class="checkout-field checkout-field-wide" data-checkout-area <?= count($deliveryState['areas'])>1?'':'hidden' ?>><span>Choose your delivery area</span><select class="checkout-input" name="zone_id" <?= count($deliveryState['areas'])>1?'required':'' ?> <?= !$deliveryState['areas']?'disabled':'' ?>><option value="">Choose your area</option><?php foreach($deliveryState['areas'] as $area):?><option value="<?= e($area['id']) ?>" <?= (string)($deliveryState['selected']??'')===(string)$area['id']?'selected':'' ?>><?= e($area['name']) ?> — <?= money(Money::decimal($area['fee'])) ?> delivery</option><?php endforeach;?></select><small>Choose the area for your address. The delivery charge depends on this choice.</small></label><p class="checkout-note checkout-field-wide" data-delivery-feedback role="status" aria-live="polite"><?= e($deliveryState['error']) ?></p>
<label class="checkout-field checkout-field-wide"><span>Payment</span><select class="checkout-input" name="payment_method" required><?php foreach($choices as $key=>$label): ?><option value="<?= e($key) ?>" <?= (string)($form_values['payment_method']??'')===(string)$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label></div><p><?= !empty($store->config['features']['checkout_test_mode'])?'Preview TEST checkout: no online charge will be made. Choose the temporary manual payment option to test this order.':(!$choices?'Online payment is currently unavailable. Please try again later.':'Pay online to confirm your order.') ?></p><p>Items subtotal: <strong><?= Money::display($quote['subtotal']) ?></strong>. Delivery and applicable taxes appear on the next step.</p><p>Use “Review &amp; place order” below to check your final total.</p></form><aside class="checkout-card checkout-help summary"><p class="checkout-step">A little closer to your next meal</p><h2>Fresh for your chosen meal</h2><p>Your meal and delivery date come from your cart. To change them, return to the menu and start a fresh order.</p><div class="totals"><div><span>Items</span><span><?= Money::display($quote['subtotal']) ?></span></div><div><span>Delivery charge</span><span data-delivery-fee><?= $deliveryState['fee']!==null?money(Money::decimal($deliveryState['fee'])):'Enter pincode / choose area' ?></span></div><div class="grand"><span>Estimated total</span><span data-delivery-total><?= money(Money::decimal($quote['subtotal']+($deliveryState['fee']??0))) ?></span></div></div><p class="checkout-note">Your delivery charge, any tax and final total appear on the review page before you place the order.</p><ol><li>Add your contact and delivery details.</li><li>Review availability, delivery charges and the final total.</li><li>Place your order and complete your chosen payment method.</li></ol><a class="checkout-back" href="/cart/">← Back to your cart</a></aside></div></section>

<div class="checkout-action-bar" role="region" aria-label="Continue checkout"><div class="wrap checkout-action-inner"><p><strong>Ready to order?</strong><span>Review your final total, then confirm your order.</span></p><button class="btn btn-primary btn-lg" type="submit" form="delivery-details" <?= !$choices?'disabled':'' ?>>Review &amp; place order →</button></div></div>

